import {icon,escapeHTML as esc} from './ui.js';
import {bindValidatedForm,validateRegistration} from './validation.js';

export const departments=['Legislative Services','Administrative Services','Office of the Secretary','Finance Services','Senator’s Office','Other Senate office'];
const field=(name,label,control,help)=>`<div class="field" data-field="${name}"><label class="form-label" for="reg-${name}">${label} <span class="required-mark" aria-hidden="true">*</span></label>${control}<p class="form-hint" id="reg-${name}-help">${help}</p></div>`;
const input=(name,type,extra='')=>`<input class="form-control" id="reg-${name}" name="${name}" type="${type}" aria-describedby="reg-${name}-help" required ${extra}>`;
const today=()=>new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Manila',year:'numeric',month:'2-digit',day:'2-digit'});
function birthBounds(){const day=today(),max=new Date(day+'T12:00:00Z'),min=new Date(day+'T12:00:00Z');max.setUTCFullYear(max.getUTCFullYear()-18);min.setUTCFullYear(min.getUTCFullYear()-101);min.setUTCDate(min.getUTCDate()+1);return {min:min.toISOString().slice(0,10),max:max.toISOString().slice(0,10)};}

export function renderRegistration(){return `<div class="form-intro"><span class="control-count">Member registration</span><h2>Your next chapter starts here.</h2><p>Create a fictional member account to explore your cooperative.</p></div><form id="register-form" novalidate aria-describedby="registration-instructions"><p id="registration-instructions" class="form-instructions">All fields marked <span class="required-mark">*</span> are required. Use fictional details for this demo.</p><div class="form-error-summary" data-error-summary hidden tabindex="-1" role="alert"></div>
<fieldset class="form-section"><legend>Your personal details</legend><div class="form-grid">
${field('fullName','Full name',input('fullName','text','minlength="2" maxlength="70" autocomplete="name" placeholder="e.g. Alex Rivera"'),'Enter 2–70 characters, as they should appear on your profile.')}
${field('email','Email address',input('email','email','maxlength="120" autocomplete="email" placeholder="e.g. alex@example.com"'),'Use a valid email address that is not already in the demo.')}
${field('phone','Mobile number',input('phone','tel','maxlength="20" autocomplete="tel" placeholder="09171234567" inputmode="tel"'),'Use 09 followed by 9 digits, or +639 followed by 9 digits.')}
${field('birthDate','Date of birth',input('birthDate','date',`min="${birthBounds().min}" max="${birthBounds().max}" autocomplete="bday"`),'This sample form accepts adult members aged 18–100.')}
</div></fieldset>
<fieldset class="form-section"><legend>Your employment</legend><div class="form-grid">
${field('department','Department',`<select class="form-select" id="reg-department" name="department" required aria-describedby="reg-department-help"><option value="">Select a department</option>${departments.map(d=>`<option>${esc(d)}</option>`).join('')}</select>`,'Choose the Senate office or department for your demo account.')}
${field('employmentType','Employment type',`<select class="form-select" id="reg-employmentType" name="employmentType" required aria-describedby="reg-employmentType-help"><option value="">Select employment type</option><option>Permanent</option><option>Contractual</option><option>Coterminous</option></select>`,'Select the category that matches your fictional employment.')}
${field('employeeId','Employee reference',input('employeeId','text','pattern="(?:[A-Za-z0-9]|-){3,24}" minlength="3" maxlength="24" placeholder="e.g. DEMO-0186"'),'Use 3–24 letters, numbers or hyphens. Enter a fictional reference.')}
${field('income','Monthly income (PHP)',input('income','number','min="0.01" max="10000000" step="0.01" placeholder="42000" inputmode="decimal"'),'Enter an amount above ₱0 and no more than ₱10,000,000.')}
</div></fieldset>
<fieldset class="form-section"><legend>Your demo sign-in</legend><div class="form-grid">
${field('password','Password',input('password','password','minlength="8" maxlength="64" autocomplete="new-password" placeholder="Create a demo password"'),'Use 8–64 characters, including a letter and a number.')}
${field('confirmPassword','Confirm password',input('confirmPassword','password','minlength="8" maxlength="64" autocomplete="new-password" placeholder="Enter the same password"'),'Both password fields must match. Use a fictional password.')}
</div><label class="form-check mt-3"><input class="form-check-input" type="checkbox" id="registration-show-password"><span class="form-check-label">Show passwords</span></label></fieldset>
<fieldset class="form-section"><legend>Stay connected</legend><fieldset class="field" data-field="preferredContact"><legend class="form-label">Preferred contact method <span class="required-mark" aria-hidden="true">*</span></legend><div class="radio-options"><label class="form-check"><input type="radio" class="form-check-input" id="reg-contact-email" name="preferredContact" value="Email" required aria-describedby="reg-contact-help"><span class="form-check-label">Email</span></label><label class="form-check"><input type="radio" class="form-check-input" id="reg-contact-sms" name="preferredContact" value="SMS" required aria-describedby="reg-contact-help"><span class="form-check-label">SMS</span></label></div><p class="form-hint" id="reg-contact-help">Choose a preference. This prototype does not send email or text messages.</p></fieldset>
<div class="field form-check form-switch" data-field="notifications"><input class="form-check-input" role="switch" type="checkbox" id="reg-notifications" name="notifications" checked aria-describedby="reg-notifications-help"><label class="form-check-label" for="reg-notifications">Show application updates in the demo</label><p class="form-hint" id="reg-notifications-help">Save your notification preference with your member profile.</p></div>
<div class="field form-check" data-field="terms"><input type="checkbox" class="form-check-input" id="reg-terms" name="terms" required aria-describedby="reg-terms-help"><label class="form-check-label" for="reg-terms">I confirm these details are fictional and for this prototype. <span class="required-mark" aria-hidden="true">*</span></label><p class="form-hint" id="reg-terms-help">Your demo record is stored in this browser after verification.</p></div></fieldset>
<div class="form-actions"><button class="btn btn-light" type="reset">Clear registration form</button><button class="btn btn-primary" type="submit" id="register-submit">Create member account ${icon('arrow-right')}</button></div><div class="form-success mt-3" id="registration-status" role="status" hidden></div></form><p class="registration-link">Already a member? <button id="back-login" type="button">Back to sign in</button></p>`;}

export function bindRegistration(ctx){const form=document.querySelector('#register-form');if(!form)return;
document.querySelector('#registration-show-password').addEventListener('change',e=>{for(const name of ['password','confirmPassword'])form.elements.namedItem(name).type=e.target.checked?'text':'password';});
bindValidatedForm(form,{validate:v=>validateRegistration(v,{existingEmails:[...ctx.state.members,...ctx.state.users].map(m=>m.email),today:today()}),onValid:async v=>{
  const button=document.querySelector('#register-submit');button.disabled=true;button.textContent='Preparing your demo account…';
  try{const credential=await createDemoCredential(v.password);const fullName=v.fullName.trim();const member={id:'M-DEMO-'+Date.now().toString(36).toUpperCase(),name:fullName,initials:fullName.split(/\s+/).slice(0,2).map(p=>p[0]).join('').toUpperCase(),email:v.email.trim().toLowerCase(),phone:v.phone.trim(),birthDate:v.birthDate,age:ageAt(v.birthDate),department:v.department,employmentType:v.employmentType,employeeId:v.employeeId.trim(),income:Number(v.income),preferredContact:v.preferredContact,notifications:Boolean(v.notifications),status:'Pending',savings:0,joined:new Date().toLocaleDateString('en-PH',{year:'numeric',month:'long',day:'numeric'}),demoCredential:credential};
    await ctx.onRegistered(member);
  }finally{if(button.isConnected){button.disabled=false;button.innerHTML=`Create member account ${icon('arrow-right')}`;}}
},onReset:()=>{document.querySelector('#registration-show-password').checked=false;for(const name of ['password','confirmPassword'])form.elements.namedItem(name).type='password';document.querySelector('#registration-status').hidden=true;}});}

function ageAt(date){const now=new Date(),dob=new Date(date+'T00:00:00');return now.getFullYear()-dob.getFullYear()-((now.getMonth()<dob.getMonth()||(now.getMonth()===dob.getMonth()&&now.getDate()<dob.getDate()))?1:0);}
function toHex(buffer){return Array.from(new Uint8Array(buffer),v=>v.toString(16).padStart(2,'0')).join('');}
async function derive(password,salt){const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);return toHex(await crypto.subtle.deriveBits({name:'PBKDF2',salt,iterations:120000,hash:'SHA-256'},key,256));}
export async function createDemoCredential(password){const salt=crypto.getRandomValues(new Uint8Array(16));return {salt:toHex(salt),hash:await derive(password,salt)};}
export async function verifyDemoCredential(password,credential){if(!credential?.salt||!credential.hash)return false;const salt=Uint8Array.from(credential.salt.match(/.{2}/g)||[],v=>parseInt(v,16));return await derive(password,salt)===credential.hash;}
